"""R3g 差異部署：正式版 r3f 原始碼 → insti_query_r1.py 換成 R3g（上櫃收盤價 dailyQuotes 備援＋三大法人★說明如實）。
app.py 與其他檔案不動。用法：python3 -B r3g_delta.py --src DIR --cand DIR
"""
import base64, gzip, hashlib, os, subprocess, sys
APP_OLD = "47e54b77f4f1fa97"
INSTI_OLD = "ae1786b8ebaa819c"
INSTI_NEW = "ebd3015cd69be41e04bb1b7955d4d8bc56663ade402c42948a53fe21df57db16"
INSTI_GZ = ""
sha = lambda b: hashlib.sha256(b).hexdigest()
def need(c, m):
    if not c:
        print("[R3G_STOP]", m); sys.exit(1)
a = sys.argv[1:]
src, cand = a[a.index("--src") + 1], a[a.index("--cand") + 1]
app_b, ins_b = open(os.path.join(src, "app.py"), "rb").read(), open(os.path.join(src, "insti_query_r1.py"), "rb").read()
need(sha(app_b).startswith(APP_OLD), "app.py 不是正式版 r3f " + sha(app_b)[:16])
need(sha(ins_b).startswith(INSTI_OLD), "insti 不是正式版 R3f " + sha(ins_b)[:16])
new_ins = gzip.decompress(base64.b64decode(INSTI_GZ))
need(sha(new_ins) == INSTI_NEW, "內嵌 R3g 檔 SHA 不符")
compile(new_ins, "insti_query_r1.py", "exec")
need(not os.path.exists(cand), "候選目錄已存在")
os.makedirs(os.path.dirname(cand), exist_ok=True)
subprocess.run(["cp", "-al", src, cand], check=True)
tmp = os.path.join(cand, ".insti_query_r1.py.tmp")
open(tmp, "wb").write(new_ins)
os.replace(tmp, os.path.join(cand, "insti_query_r1.py"))
need(os.stat(os.path.join(cand, "insti_query_r1.py")).st_nlink == 1, "仍是硬連結")
need(sha(open(os.path.join(src, "insti_query_r1.py"), "rb").read()) == sha(ins_b), "基底被改動")
print(f"[R3G_PATCHED] candidate={cand} app={sha(app_b)[:16]}(不變) insti={sha(new_ins)[:16]}")
